CREATE TABLE public.old_gold_accounts(branch_id text NOT NULL REFERENCES public.branches(id),purity integer NOT NULL CHECK(purity BETWEEN 1 AND 24),weight numeric NOT NULL DEFAULT 0 CHECK(weight>=0),cost_lkr numeric NOT NULL DEFAULT 0 CHECK(cost_lkr>=0),PRIMARY KEY(branch_id,purity));
GRANT SELECT ON public.old_gold_accounts TO authenticated; GRANT ALL ON public.old_gold_accounts TO service_role;
ALTER TABLE public.old_gold_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY old_gold_accounts_read ON public.old_gold_accounts FOR SELECT TO authenticated USING(public.staff_can('View costs and profit',branch_id) AND (public.staff_can('Manage stock',branch_id) OR public.staff_can('View reports',branch_id)));
CREATE TABLE public.old_gold_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),branch_id text NOT NULL REFERENCES public.branches(id),purity integer NOT NULL CHECK(purity BETWEEN 1 AND 24),kind text NOT NULL CHECK(kind IN('Buy','Sell')),weight numeric NOT NULL CHECK(weight>0),pricing_unit text NOT NULL CHECK(pricing_unit IN('Gram','Pound (8g)')),unit_price numeric NOT NULL CHECK(unit_price>0),total_lkr numeric NOT NULL,cost_lkr numeric NOT NULL,profit_lkr numeric NOT NULL,customer_name text NOT NULL DEFAULT '',customer_phone text NOT NULL DEFAULT '',method text NOT NULL CHECK(method IN('Cash','Bank Transfer','Card')),reference text NOT NULL DEFAULT '',note text NOT NULL DEFAULT '',date date NOT NULL DEFAULT (now() AT TIME ZONE 'Asia/Colombo')::date,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL);
GRANT SELECT ON public.old_gold_entries TO authenticated; GRANT ALL ON public.old_gold_entries TO service_role;
ALTER TABLE public.old_gold_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY old_gold_entries_read ON public.old_gold_entries FOR SELECT TO authenticated USING(public.staff_can('View costs and profit',branch_id) AND (public.staff_can('Manage stock',branch_id) OR public.staff_can('View reports',branch_id)));
CREATE OR REPLACE FUNCTION public.record_old_gold(p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE b text:=p->>'branch_id';k text:=p->>'kind';q integer:=(p->>'purity')::integer;w numeric:=(p->>'weight')::numeric;price numeric:=(p->>'unit_price')::numeric;u text:=p->>'pricing_unit';m text:=p->>'method';t numeric;c numeric;profit numeric:=0;holding public.old_gold_accounts;eid uuid;
BEGIN
IF NOT(public.staff_can('Manage stock',b) AND public.staff_can('View costs and profit',b)) THEN RAISE EXCEPTION 'Stock management and cost/profit permissions required';END IF;
IF k IS NULL OR k NOT IN('Buy','Sell') OR q IS NULL OR q<1 OR q>24 OR w IS NULL OR w<=0 OR w>1000000000 OR w::text IN('NaN','Infinity','-Infinity') OR w<>round(w,3) OR price IS NULL OR price<=0 OR price>1000000000 OR price::text IN('NaN','Infinity','-Infinity') OR price<>round(price,2) OR u IS NULL OR u NOT IN('Gram','Pound (8g)') OR m IS NULL OR m NOT IN('Cash','Bank Transfer','Card') THEN RAISE EXCEPTION 'Enter valid purity, weight (3 decimals), unit price (2 decimals) and payment method';END IF;
t:=round(w*price/CASE WHEN u='Pound (8g)' THEN 8 ELSE 1 END,2);IF t<=0 THEN RAISE EXCEPTION 'Total must be at least LKR 0.01';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('old-gold-'||b||'-'||q,0));
INSERT INTO public.old_gold_accounts(branch_id,purity) VALUES(b,q) ON CONFLICT DO NOTHING;
SELECT * INTO holding FROM public.old_gold_accounts WHERE branch_id=b AND purity=q FOR UPDATE;
IF k='Buy' THEN c:=t;UPDATE public.old_gold_accounts SET weight=weight+w,cost_lkr=cost_lkr+t WHERE branch_id=b AND purity=q;
ELSE IF holding.weight<w THEN RAISE EXCEPTION 'Sale exceeds available old-gold weight for this purity';END IF;c:=CASE WHEN w=holding.weight THEN holding.cost_lkr ELSE round(holding.cost_lkr*w/holding.weight,2) END;profit:=t-c;UPDATE public.old_gold_accounts SET weight=weight-w,cost_lkr=cost_lkr-c WHERE branch_id=b AND purity=q;END IF;
INSERT INTO public.old_gold_entries(branch_id,purity,kind,weight,pricing_unit,unit_price,total_lkr,cost_lkr,profit_lkr,customer_name,customer_phone,method,reference,note,created_by) VALUES(b,q,k,w,u,price,t,c,profit,trim(coalesce(p->>'customer_name','')),trim(coalesce(p->>'customer_phone','')),m,coalesce(p->>'reference',''),coalesce(p->>'note',''),auth.uid()) RETURNING id INTO eid;
RETURN eid;END $$;
REVOKE ALL ON FUNCTION public.record_old_gold(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.record_old_gold(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_old_gold() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_events(actor_id,actor_name,branch_id,category,action,description,record_id) VALUES(NEW.created_by,coalesce((SELECT display_name FROM public.profiles WHERE id=NEW.created_by),'Staff'),NEW.branch_id,'Old gold',NEW.kind,CASE WHEN NEW.kind='Buy' THEN 'Bought ' ELSE 'Sold ' END||NEW.weight||'g of '||NEW.purity||'K old gold for LKR '||NEW.total_lkr,NEW.id::text);RETURN NEW;END $$;
CREATE TRIGGER audit_old_gold AFTER INSERT ON public.old_gold_entries FOR EACH ROW EXECUTE FUNCTION public.audit_old_gold();